import sys; sys.path.insert(0, '.')
from docx_helpers import *
def build(path):
    d = Doc('INTERNAL - Disclosure Q&A', 'Jalour Developments  |  INTERNAL ONLY. Do not include in any pitch pack.'); dd = d.d
    d.p('INTERNAL ONLY. NOT FOR INVESTORS.', bold=True, size=11, color=RGBColor(0xA2, 0x3B, 0x3B))
    d.p('Disclosure Q&A for investor conversations', bold=True, size=20, color=NAVY, after=4)
    d.p('Purpose: truthful, safe answers to questions investors are likely to ask about other investors, other projects and funding. Answers may decline to give detail. They must never deny a fact. Do not store this file in, attach it to, or send it with any pitch pack.')
    d.h2('Facts the team must keep straight (do not state these to investors unprompted)')
    d.bullets(['Jalour is raising capital for two projects, Green Square and L\'avenir, from two separate investors, one per project. Each investor sees only their own project.', 'The two projects are held in separate project companies. There is no cross-collateral and no cross-default. (Counsel to confirm the entity set-up before this is said.)', 'Project funding gaps are to be covered from Jalour\'s cash reserves and from cash generated by other projects Jalour is constructing. That capacity is shared across projects and other group activity, and the packs say so.', 'Jalour may raise further capital at project or holding level and has not offered exclusivity to anyone.', 'Jalour has not guaranteed any return in either project.'])
    d.h2('Exception: the two 125M packs')
    d.p('By Jalour decision, the Green Square 125M and L\'avenir 125M packs (and only those) show the other project\'s finances: its name, financial summary and a combined cash position (Investment Memorandum section 11.2, deck slide 11, annex sheet Combined_Position). The other six packs remain strictly separate. Rules for the 125M packs:')
    d.bullets(['The packs do not mention the other project\'s investor, ticket, terms or pitch, and never state any combined or total raise. Note that two 125M tickets add to a number the investors could work out for themselves; do not confirm or discuss it.', 'Both 125M investors may compare notes. Check that the two packs agree on every shared number before either is sent.', 'Disclosing the other project\'s finances to one investor is a disclosure to a third party about the other project. Counsel should confirm confidentiality undertakings in the NDA cover this.', 'The answer to "Is Jalour raising for other projects?" stays: we do not comment on other capital providers or their terms. The packs themselves show the other project\'s finances.'])
    d.h2('Words and claims never to use')
    d.table([['Never say or write', 'Why', 'Say instead'], ['"You are the only external investor" / "the last investor"', 'May be untrue and would be a misrepresentation in due diligence', 'The balance of project funding is provided by Jalour sponsor equity, project collections and other capital sources.'], ['"Jalour funds the balance entirely from its own balance sheet"', 'May be untrue', 'Same wording as above'], ['"This is the only project we are raising for"', 'Untrue', 'Each project is held and financed separately; your investment has no exposure to other projects.'], ['"Exclusive" or "we will not raise other capital"', 'Not offered', 'Jalour may raise further capital at project or holding level, subject to your stated rights.'], ['Any combined programme figure, any mention of the other project\'s name, ticket, terms or investor', 'Breaches the separation of the two offers', 'We do not discuss other projects or other investors\' terms.']], [5.6, 4.6, 6.1], 'Prohibited wording', -1, font=9.5)
    d.h2('Questions and answers')
    qa = [('Is anyone else investing in this project?', 'This placement is for your ticket of the stated amount. The balance of project funding is provided by Jalour sponsor equity, project collections and other capital sources. We do not name other capital providers or their terms. Jalour may raise further capital at project or holding level, subject to your stated rights on ranking, collateral and information; anything that would rank ahead of you or encumber your earmarked units needs your consent.', 'Do not say "no one else" or "you are the only one" unless Jalour has confirmed it in writing for that project on the date of the question.'),
          ('Who funds the remainder?', 'The balance of project funding is provided by Jalour sponsor equity, project collections and other capital sources. The sources and uses table in the memorandum shows the amounts. Jalour has said it will cover project funding gaps above project cash from its cash reserves and from cash generated by other projects it is constructing; the form and cap of that undertaking are being documented.', 'Do not say "from our balance sheet".'),
          ('Is Jalour raising for other projects?', 'Jalour is a developer and may raise capital for other projects from time to time. Each project is in its own company, with no cross-collateral and no cross-default, so your investment has no exposure to them and they have none to this project. We do not discuss other projects.', 'This is true and does not give detail. Do not deny it.'),
          ('Is Jalour raising from other investors for other projects?', 'We do not comment on other projects or their capital providers. What matters for you is that your rights are set out in your agreements and that there is no cross-default.', 'Decline; do not deny.'),
          ('Will other investors get better terms?', 'Terms for each project reflect that project\'s own economics and risks. Your terms are in your agreements. We do not offer most-favoured-nation terms [Jalour to confirm].', 'Do not promise parity.'),
          ('Are you the only external investor?', 'Same answer as the first question. The balance of funding is provided by Jalour sponsor equity, project collections and other capital sources.', 'Never answer "yes".'),
          ('Does Jalour have other debt or investors at holding level?', 'Group-level borrowings and capital are shown in the audited accounts that will be in the data room [pending]. Any holding-level capital is subject to your stated rights where it affects this project.', 'Provide accounts when available. Do not deny.'),
          ('Can the other project\'s problems affect mine?', 'There is no cross-collateral or cross-default. However, Jalour\'s capacity to cover this project\'s gaps rests on its cash reserves and on cash from its other projects, so how those projects perform can affect that capacity. That is why audited accounts are provided after a non-disclosure agreement is signed and the funding undertaking is documented.', 'This is the honest point on shared sponsor capacity; do not omit it if asked about sponsor strength.'),
          ('Is cash from other projects used for mine, or mine for others?', 'Jalour has said it will cover gaps in this project from its cash reserves and cash from other projects it is constructing. Surplus cash from this project, once the payment priority covenant is satisfied, belongs to the project company and its owners and can be distributed to Jalour; what Jalour does with it at group level is not restricted by your agreements, except through the covenants you have.', 'Do not say cash is segregated or ring-fenced. Do not deny that group cash is shared.'),
          ('Is there a guarantee?', 'No. Jalour does not guarantee the return. Protections are the allocation or earmark of specific units, a payment priority covenant, information rights and the funding undertaking.', ''),
          ('Is the offer exclusive?', 'No exclusivity is offered. Further capital may be raised at project or holding level, subject to your stated rights.', ''),
          ('What is the total raise?', 'The amount for this project is the ticket and the funding plan in the memorandum. We do not discuss any wider programme.', 'Never state or hint at any combined figure.')]
    for q, a, n in qa:
        d.h3(q); d.p(a)
        if n: d.p('Note to team: ' + n, italic=True, size=9.5, color=GREY)
    d.h2('Escalation and record-keeping')
    d.bullets(['Any question not covered here goes to the managing director and counsel before it is answered.', 'Record questions and answers given in each investor conversation.', 'If an answer given earlier turns out to be wrong or has been overtaken, correct it in writing promptly.', 'Before any investor signs, counsel confirms that statements in the pack on other investors and other projects are still accurate.'])
    d.save(path)
if __name__ == '__main__': build(sys.argv[1]); print('ok')
